<?php
declare(strict_types=1); namespace App\Controllers;
use App\Core\Request;use App\Core\Response;use App\Services\DiscountService;
class DiscountController {private function out(array$r,int$ok=200):void{if(isset($r['error']))Response::json(['message'=>$r['error'],'conflicts'=>$r['conflicts']??null],$r['status']??422);Response::json($r,$ok);}public function index():void{Response::json((new DiscountService())->all());}public function show():void{$r=(new DiscountService())->one((int)Request::param('id'));if(!$r)Response::json(['message'=>'Réduction introuvable'],404);Response::json($r);}public function preview():void{$this->out((new DiscountService())->preview(Request::json()));}public function store():void{$this->out((new DiscountService())->create(Request::json()),201);}public function cancel():void{$this->out((new DiscountService())->cancel((int)Request::param('id'),Request::json()));}public function replace():void{$this->out((new DiscountService())->replace((int)Request::param('id'),Request::json()),201);}public function history():void{$this->out(['history'=>(new DiscountService())->historyFor((int)Request::param('id'))]);}}
